"""A Level Pure Mathematics with Mechanics (Upper Sixth): practice sets for Statics of Rigid Bodies.

KKEVO draft content. g = 9.8 m/s^2 unless a question says otherwise.
"""

from .dsl import *  # noqa: F403

COURSE = ("pure-mathematics-with-mechanics", "upper-sixth")

MOD = "Statics of Rigid Bodies"


def Q(prompt, right, wrongs, steps, concept, skill, hint, pos, feedback="", diagram="", diagram_alt=""):
    """Four-option question: `wrongs` is three (text, why) pairs; the correct option goes at index `pos`."""
    options = [C(t, why=w) for t, w in wrongs]
    options.insert(pos, C(right, correct=True))
    return MC(prompt, options, steps=steps, concept=concept, skill=skill, hint=hint, feedback=feedback,
              diagram=diagram, diagram_alt=diagram_alt)


